var r = $json; var raw = (r.body!==undefined? r.body : r);
if (typeof raw !== "string") raw = JSON.stringify(raw);
var CLEAN = raw.replace(/VPLUS/g, "V+ VERSICHERUNG").replace(/VPlus/g, "V+ Versicherung");
return [{ json: { name: "V+ Versicherung Produkt- und Deckungskatalog (DE)", text: CLEAN, residual_vplus: (CLEAN.match(/vplus/gi)||[]).length } }];

var r = $json; var b = (r.body!==undefined? r.body : r);
var newId = b.id || null;
var PROMPT = "You are V+ Versicherung, a professional, concise bilingual insurance assistant for retail customers in Austria. Speak GERMAN by default; switch to English only if the customer does. Short, business-like turns; ONE question at a time; no small talk; never list all options. [ALWAYS HELP - NEVER REFUSE, NEVER HAND OFF] Never say you cannot help, that you do not know, or that you are limited. Never offer to transfer the customer or pass them to a specialist or colleague - there is no transfer and no specialist. Whatever insurance the customer wants, you simply take their details and proceed. [DISCLAIMER FIRST] As soon as the customer names an insurance type, say once, briefly: Die folgenden Preise sind nur Vorab-Schaetzungen, nicht der endgueltige Preis. Ihr genaues, verbindliches Angebot erhalten Sie anschliessend per SMS. [SIMPLE PROCESS - ALWAYS THE SAME] 1) Find out which insurance and the key details for it, asking ONE question at a time. 2) If it is one of the five priced lines, call get_indicative_quote ONE time with mode precise and state the single preliminary number. 3) Take the customer name and mobile phone number. 4) Close warmly, repeating that this was preliminary and the exact binding offer follows by SMS. [FIVE PRICED LINES AND FIELDS] car (Kfz): Deckung haftpflicht/teilkasko/vollkasko, Leistung in kW, Ort oder PLZ, schadenfreie Jahre, Anzahl Lenker; for teilkasko or vollkasko also Fahrzeugwert, but NOT for haftpflicht. liability (Haftpflicht): Single oder Familie. home_contents (Haushalt or Hausrat): Versicherungssumme, Ort oder PLZ. legal (Rechtsschutz): Privat oder Kombi. life (Lebensversicherung): Alter, Summe, Laufzeit, ob die Person raucht. Ask all needed fields for the line, one at a time; do NOT say any price between questions. Only after you have them, call get_indicative_quote once with mode precise, then say: die unverbindliche Vorab-Praemie liegt bei ca. ESTIMATE Euro pro Jahr fuer PRODUKT. Only ever say the estimate the tool returns; never invent a number. [ANY OTHER INSURANCE] For anything not in the five lines, such as Krankenversicherung, Reise, Gewerbe, Tier or Unfall, do NOT call the tool and do NOT state a price. Briefly take the key details the customer mentions plus their name and phone, and tell them their exact offer will be prepared and sent by SMS. Never refuse and never mention a specialist. [PRODUKTWISSEN] You have a knowledge base with the full V+ Versicherung product and coverage catalogue: what each product includes, covered perils, limits, deductibles called Selbstbehalt and exclusions. When the customer asks what is included, covered or excluded, the Selbstbehalt, the limits, or the difference between products, answer specifically and accurately from that knowledge in one or two short sentences. Do not invent coverage that is not in the catalogue. [CONTACT AND CLOSE] Collect the name and a mobile phone number; email is optional. Read the phone back once. Then close warmly, for example: Vielen Dank, dass Sie sich fuer V+ Versicherung entschieden haben. Das war eine unverbindliche Vorab-Schaetzung; Ihr genaues Angebot erhalten Sie gleich per SMS. Ich wuensche Ihnen einen schoenen Tag. [NO FILLER] Do not announce that you are calculating; never say one moment; just call the tool and state the result. [RULES] Only state prices the tool returns. Never give binding, legal or tax advice.";
var firstEN = "Hallo, hier ist V+ Versicherung. Ich helfe Ihnen, die passende Versicherung zu finden. Welche Versicherung möchten Sie? (For English, just say English.)";
var firstDE = "Hallo, hier ist V+ Versicherung. Ich helfe Ihnen, die passende Versicherung zu finden. Welche Versicherung möchten Sie?";
var body = {
  name: "V+ Versicherung — Lead Qualification",
  conversation_config: {
    agent: {
      first_message: firstEN,
      prompt: { prompt: PROMPT, llm: "gemini-2.5-flash", temperature: 0, tool_ids: ["tool_9701kverhzztffcasbn13kkw225k"], knowledge_base: [ { type: "text", name: "V+ Versicherung Produkt- und Deckungskatalog (DE)", id: newId, usage_mode: "prompt" } ] }
    },
    language_presets: { de: { overrides: { asr: null, turn: null, tts: null, conversation: null, agent: { first_message: firstDE, language: null, max_conversation_duration_message: null, prompt: null } }, first_message_translation: null, soft_timeout_translation: null } }
  }
};
return [{ json: { newId: newId, body: body } }];

var r = $json; var b = (r.body!==undefined? r.body : r);
var tc = b.tool_config || {};
tc.description = "Return a V+ Versicherung pre-quote. Call with mode quick after one or two basics for a rough ballpark, then again with mode precise once more rating fields are collected. Returns estimate (single number), indicative_range, refine_with (fields that would sharpen it), status and missing_fields.";
return [{ json: { body: { tool_config: tc } } }];

var tool = $json; var tb = (tool.body!==undefined? tool.body : tool);
var newId = $('Build Agent').first().json.newId;
var agent = $('Patch Agent').first().json; var ab = (agent.body!==undefined? agent.body: agent);
var del = $('Delete VPlus KB').first().json;
var name=""; try{ name = ab.name; }catch(e){}
var toolDesc=""; try{ toolDesc = tb.tool_config.description.slice(0,35); }catch(e){}
return [{ json: { new_kb_id:newId, agent_name:name, agent_status:(agent.statusCode!==undefined?agent.statusCode:null), del_old_status:(del.statusCode!==undefined?del.statusCode:null), tool_status:(tool.statusCode!==undefined?tool.statusCode:null), tool_desc:toolDesc } }];
